#!/bin/sh
# Pick which feature build the TV app runs.
#
# The source of truth stays the Flutter app's feature JSON. This script turns
# the chosen file into a synchronous JS global so the TV app can boot without
# fetching a local JSON file (fetch() over file:// is not reliable on Tizen).
#
# Usage, from anywhere:
#   ./scripts/use-build.sh ef        # assets/features.ef.json
#   ./scripts/use-build.sh reduced   # assets/features.json
#
# The generated file is js/features.generated.js. Do not edit it by hand.

set -eu

SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
ROOT=$(CDPATH= cd -- "$SCRIPT_DIR/.." && pwd)
cd "$ROOT"

variant=${1:-ef}

case "$variant" in
  ef)
    src="../assets/features.ef.json"
    ;;
  reduced)
    src="../assets/features.json"
    ;;
  -h|--help|help)
    sed -n '2,14p' "$0" | sed 's/^# \{0,1\}//'
    exit 0
    ;;
  *)
    echo "unknown build: $variant (expected ef or reduced)" >&2
    exit 2
    ;;
esac

if [ ! -f "$src" ]; then
  echo "missing feature file: $ROOT/$src" >&2
  exit 1
fi

{
  echo "/* GENERATED by scripts/use-build.sh from ${src#../} — do not edit. */"
  echo "window.SN_FEATURES ="
  cat "$src"
  echo ";"
} > js/features.generated.js

echo "TV build: $variant"
echo "  source: ${src#../}"
echo "  wrote:  js/features.generated.js"
